import{_ as r}from"./chunks/vps产品管理.O6ocl-Gm.js";import{_ as o,o as p,c as n,a2 as a}from"./chunks/framework.BXzK3EA4.js";const g="/assets/%E5%AE%89%E5%85%A8%E7%BB%84%E9%A1%B5%E9%9D%A2.C_S1nUBO.png",i="/assets/%E5%88%9B%E5%BB%BA%E5%AE%89%E5%85%A8%E7%BB%8411.9qCsEEVJ.png",t="/assets/%E5%88%9B%E5%BB%BA%E6%96%B0%E7%9A%84%E5%AE%89%E5%85%A8%E7%BB%84.Cw-sDzMz.png",l="/assets/%E5%AE%89%E5%85%A8%E7%BB%84%E7%BC%96%E8%BE%91.FSWT70jf.png",e="/assets/%E6%B7%BB%E5%8A%A0%E5%AE%89%E5%85%A8%E7%BB%84%E8%A7%84%E5%88%9911.Bwhq-6Qz.png",E="/assets/%E5%88%9B%E5%BB%BA%E6%96%B0%E7%9A%84%E5%AE%89%E5%85%A8%E7%BB%84%E8%A7%84%E5%88%99.CxL_OMn4.png",A="/assets/%E5%AE%89%E5%85%A8%E7%BB%84%E9%9D%A2%E6%9D%BF%E6%B7%BB%E5%8A%A011.0yyHlEfl.png",c="/assets/%E5%BA%94%E7%94%A8%E5%88%9B%E5%BB%BA%E5%AE%89%E5%85%A8%E7%BB%8411.DGjZJq6z.png",B="/assets/%E7%A1%AE%E8%AE%A4%E5%BA%94%E7%94%A8%E5%AE%89%E5%85%A8%E7%BB%84.pjCX1oX1.png",m="/assets/%E5%BA%94%E7%94%A8%E5%AE%89%E5%85%A8%E7%BB%84%E6%88%90%E5%8A%9F.CAAZRx2q.png",_="/assets/%E5%AE%89%E5%85%A8%E7%BB%84%E5%8F%96%E6%B6%88%E5%BA%94%E7%94%A811.pPe3QIet.png",h="/assets/%E7%AE%A1%E7%90%86%E5%AE%89%E5%85%A8%E7%BB%8411.CG9I16_2.png",d="/assets/%E7%AE%A1%E7%90%86%E5%AE%89%E5%85%A8%E7%BB%84%E8%A7%84%E5%88%9911.Dy8W_BaA.png",u="/assets/%E5%88%A0%E9%99%A4%E5%AE%89%E5%85%A8%E7%BB%8411.20DRsrCU.png",P="/assets/%E7%A1%AE%E8%AE%A4%E5%88%A0%E9%99%A4.DQ-G0RF_.png",D=JSON.parse('{"title":"安全组","description":"","frontmatter":{"title":"安全组"},"headers":[],"relativePath":"vps/manage-vps/security-groups.md","filePath":"vps/manage-vps/security-groups.md","lastUpdated":1788185904000}'),q={name:"vps/manage-vps/security-groups.md"};function b(f,s,S,k,V,x){return p(),n("div",null,[...s[0]||(s[0]=[a('<p>安全组是一种虚拟防火墙，具备数据包过滤功能，用于设置 VPS 实例的网络访问控制，是重要的网络安全隔离手段。</p><p>您在购买并开通 VPS 后，系统会自动为您创建默认安全组并关联至该实例。除了默认安全组，您还可以根据业务需求创建自定义安全组并关联至实例。</p><hr><h3 id="安全组管理面板" tabindex="-1">安全组管理面板 <a class="header-anchor" href="#安全组管理面板" aria-label="Permalink to &quot;安全组管理面板&quot;">​</a></h3><p>本文介绍如何在安全组管理面板对安全组进行操作。</p><h4 id="添加安全组" tabindex="-1">添加安全组 <a class="header-anchor" href="#添加安全组" aria-label="Permalink to &quot;添加安全组&quot;">​</a></h4><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">Raksmart 控制台</a>。</p></li><li><p>在左侧导航单击 <strong>VPS</strong>，进入<strong>我的产品与服务</strong> - <strong>VPS</strong>面板。</p><p><img src="'+r+'" alt="vps产品管理.png"></p></li><li><p>在<strong>分类</strong>选项里，单击<strong>安全组</strong>，进入<strong>安全组</strong>页面。</p><p><img src="'+g+'" alt="安全组页面.png"></p></li><li><p>单击<strong>添加</strong>。</p><p><img src="'+i+'" alt="创建安全组11.png"></p></li><li><p>在创建新的安全组页面，自定义安全组<strong>名称</strong>，例如 “vps 安全组”；选择是否使用<strong>默认</strong>安全组。</p><p><img src="'+t+'" alt="创建新的安全组.png"></p></li><li><p>单击<strong>保存</strong>。</p></li></ol><h4 id="添加安全组规则" tabindex="-1">添加安全组规则 <a class="header-anchor" href="#添加安全组规则" aria-label="Permalink to &quot;添加安全组规则&quot;">​</a></h4><p>如果需要对安全组中的安全规则进行调整，可以修改已有的安全组规则，也可以自定义安全组规则。</p><ol><li><p>在安全组列表中，找到已添加的安全组，例如 “vps 安全组”，单击右侧的<strong>编辑</strong>按钮。进入<strong>安全组规则</strong>页面。</p><p><img src="'+l+'" alt="安全组编辑.png"></p></li><li><p>单击<strong>添加</strong>，进入<strong>创建新的安全组规则</strong>页面。也可单击右侧<strong>编辑</strong>按钮对现有规则进行调整。</p><p><img src="'+e+'" alt="添加安全组规则11.png"></p></li><li><p>填写合适的<strong>远程 IP</strong>、<strong>方向</strong>、<strong>协议</strong>、<strong>最小端口</strong>和<strong>最大端口</strong>，并单击<strong>保存</strong>。</p><p><img src="'+E+'" alt="创建新的安全组规则.png"></p></li></ol><hr><h3 id="vps-安全组面板相关操作" tabindex="-1">VPS 安全组面板相关操作 <a class="header-anchor" href="#vps-安全组面板相关操作" aria-label="Permalink to &quot;VPS 安全组面板相关操作&quot;">​</a></h3><p>本文介绍如何在 VPS 操作界面对安全组进行管理。</p><h4 id="添加安全组-1" tabindex="-1">添加安全组 <a class="header-anchor" href="#添加安全组-1" aria-label="Permalink to &quot;添加安全组&quot;">​</a></h4><p>您可以在 VPS 管理页面安全组面板添加新的安全组。</p><ol><li><p>在VPS的<strong>管理产品</strong>页面，单击<strong>安全组</strong>面板。</p></li><li><p>单击<strong>添加</strong>按钮。</p><p><img src="'+A+'" alt="安全组面板添加11.png"></p></li><li><p>在创建新的安全组页面，输入安全组名称和选择是否使用默认安全组。</p><p><img src="'+t+'" alt="创建新的安全组.png"></p></li><li><p>单击<strong>保存</strong>。</p></li></ol><h4 id="应用安全组" tabindex="-1">应用安全组 <a class="header-anchor" href="#应用安全组" aria-label="Permalink to &quot;应用安全组&quot;">​</a></h4><p>安全组可以应用到 VPS 服务器上。</p><ol><li><p>在VPS的<strong>管理产品</strong>页面，单击<strong>安全组</strong>面板。</p></li><li><p>选择目标安全组，单击<strong>应用</strong>。</p><p><img src="'+c+'" alt="应用创建安全组11.png"></p></li><li><p>在提示页面中单击<strong>确认应用</strong>。</p><p><img src="'+B+'" alt="确认应用安全组.png"></p></li><li><p>成功应用后页面提示如下信息。</p><p><img src="'+m+'" alt="应用安全组成功.png"></p></li></ol><h4 id="取消应用安全组" tabindex="-1">取消应用安全组 <a class="header-anchor" href="#取消应用安全组" aria-label="Permalink to &quot;取消应用安全组&quot;">​</a></h4><p>当您需要更换安全组，需先取消当前安全组，再绑定新安全组。</p><blockquote><p><strong>注意</strong></p><p>取消应用安全组后，若未及时绑定新安全组，服务器的网络访问可能会受影响，建议提前准备好新的安全组配置。</p></blockquote><ol><li><p>在<strong>安全组</strong>面板，单击<strong>取消应用</strong>。</p><p><img src="'+_+'" alt="安全组取消应用11.png"></p></li><li><p>在取消应用确认页面，单击<strong>是</strong>。</p></li></ol><h4 id="编辑安全组规则" tabindex="-1">编辑安全组规则 <a class="header-anchor" href="#编辑安全组规则" aria-label="Permalink to &quot;编辑安全组规则&quot;">​</a></h4><ol><li><p>在<strong>安全组</strong>面板，单击<strong>管理</strong>，进入编辑安全组页面。</p><p><img src="'+h+'" alt="管理安全组11.png"></p></li><li><p>可以对该安全组下的具体安全规则进行添加、编辑和删除。详细内容可参考管理安全组。</p><p><img src="'+d+'" alt="管理安全组规则11.png"></p></li></ol><h4 id="删除安全组" tabindex="-1">删除安全组 <a class="header-anchor" href="#删除安全组" aria-label="Permalink to &quot;删除安全组&quot;">​</a></h4><p>若您不再需要某个安全组，可以对其进行删除。</p><ol><li><p>在<strong>安全组</strong>面板，选择需要删除的安全组，在右侧操作列单击<strong>删除</strong>。</p><p><img src="'+u+'" alt="删除安全组11.png"></p></li><li><p>在确认页面单击<strong>是</strong>。</p><p><img src="'+P+'" alt="确认删除.png"></p></li></ol>',28)])])}const y=o(q,[["render",b]]);export{D as __pageData,y as default};
